<?php
defined('BASEPATH') or exit('No direct script access allowed');
$recordLabels=['dependent'=>'Dependentes','education'=>'Formação','award'=>'Reconhecimentos','discipline'=>'Registros disciplinares','onboarding'=>'Admissão e recepção','offboarding'=>'Desligamento e devoluções','equipment'=>'Equipamentos','compensation'=>'Histórico de valores'];
$recordFields=function(string $kind,array $data)use($field,$area,$select):void{
 $fields=match($kind){'dependent'=>['name'=>['Nome','text'],'relationship'=>['Parentesco','text'],'birth_date'=>['Nascimento','date'],'tax_identifier'=>['Identificação fiscal (opcional)','text']],'education'=>['qualification'=>['Qualificação','text'],'institution'=>['Instituição','text'],'completed_on'=>['Conclusão','date']],'award','discipline'=>['title'=>['Título','text'],'occurred_on'=>['Data','date'],'notes'=>['Descrição','area']],'onboarding','offboarding'=>['title'=>['Título do procedimento','text']],'equipment'=>['asset_code'=>['Código do equipamento','text'],'description'=>['Descrição','area'],'assigned_on'=>['Entrega','date'],'returned_on'=>['Devolução (opcional)','date']],'compensation'=>['previous_minor'=>['Valor anterior em centavos','number'],'current_minor'=>['Valor atual em centavos','number'],'currency'=>['Moeda','currency'],'effective_on'=>['Vigência','date'],'notes'=>['Motivo','area']]};
 foreach($fields as $k=>[$label,$type]){if($type==='area')$area($label,'input['.$k.']',$data[$k]??'');elseif($type==='currency')$select($label,'input['.$k.']',['BRL'=>'BRL','USD'=>'USD','EUR'=>'EUR'],$data[$k]??'BRL');else $field($label,'input['.$k.']',$data[$k]??'',$type,in_array($k,['tax_identifier','returned_on'],true)?'':($type==='number'?'required min="0" max="2000000000"':'required'));}
 if(in_array($kind,['onboarding','offboarding'],true)){echo '<div class="hr-checklist">';foreach($data['items']??[['text'=>'','done'=>0]] as $n=>$item){echo '<div class="hr-check-item">';$field('Item do procedimento','input[items]['.$n.'][text]',$item['text'],'text','required maxlength="250"');echo '<input type="hidden" name="input[items]['.$n.'][done]" value="0"><label><input type="checkbox" name="input[items]['.$n.'][done]" value="1" '.((int)$item['done']===1?'checked':'').'> Concluído</label></div>';}echo '</div><button type="button" class="hr-add-check-item">Adicionar item</button>';}
};
?>
<h3>Registros privados da pessoa</h3><p>Estes registros exigem permissão de dados sensíveis. Equipamentos, procedimentos e valores são registros internos; não alteram o login nem calculam benefícios legais.</p>
<?php foreach($records as $record){?><details><summary><?= $esc($recordLabels[$record['kind']]); ?> #<?= (int)$record['id']; ?> — <?= $esc(['pending'=>'Pendente','approved'=>'Aprovado','rejected'=>'Rejeitado','active'=>'Ativo','void'=>'Anulado'][$record['state']]??$record['state']); ?></summary>
<?php if($can('hr_sensitive','edit')&&in_array($record['state'],['active','pending'],true)){echo form_open($url(['employee'=>$employee['id']]));$hidden('record_save',['entity_id'=>$record['id'],'revision'=>$record['revision'],'employee_id'=>$employee['id'],'kind'=>$record['kind']]);?><div class="company-settings-grid"><?php $recordFields($record['kind'],$record['data']); ?></div><button type="submit">Salvar registro</button><?= form_close(); ?><?php }else{?><dl><?php foreach($record['data'] as $k=>$v){if(is_array($v)){?><dt>Procedimento</dt><dd><ul><?php foreach($v as $item){?><li><?= (int)$item['done']===1?'Concluído: ':'Pendente: '; ?><?= $esc($item['text']); ?></li><?php } ?></ul></dd><?php }else{?><dt><?= $esc(['name'=>'Nome','relationship'=>'Parentesco','birth_date'=>'Nascimento','tax_identifier'=>'Identificação','qualification'=>'Qualificação','institution'=>'Instituição','completed_on'=>'Conclusão','title'=>'Título','occurred_on'=>'Data','notes'=>'Descrição','asset_code'=>'Equipamento','description'=>'Descrição','assigned_on'=>'Entrega','returned_on'=>'Devolução','previous_minor'=>'Valor anterior (centavos)','current_minor'=>'Valor atual (centavos)','currency'=>'Moeda','effective_on'=>'Vigência'][$k]??$k); ?></dt><dd><?= nl2br($esc($v??'')); ?></dd><?php }} ?></dl><?php } ?>
<?php if($record['kind']==='dependent'&&$record['state']==='pending'&&$can('hr_sensitive','approve')){foreach(['approved'=>'Aprovar dependente','rejected'=>'Rejeitar dependente'] as $state=>$label){echo form_open($url(['employee'=>$employee['id']]));$hidden('record_state',['entity_id'=>$record['id'],'revision'=>$record['revision'],'employee_id'=>$employee['id'],'state'=>$state]);?><button type="submit"><?= $esc($label); ?></button><?= form_close(); ?><?php }} ?>
<?php if($record['state']!=='void'&&$can('hr_sensitive','edit')){echo form_open($url(['employee'=>$employee['id']]));$hidden('record_state',['entity_id'=>$record['id'],'revision'=>$record['revision'],'employee_id'=>$employee['id'],'state'=>'void']);?><button type="submit">Anular registro mantendo histórico</button><?= form_close(); ?><?php } ?>
<?php if($can('hr_files','view')){?><p><a href="<?= $esc($url(['employee'=>$employee['id'],'files_purpose'=>'record','files_object'=>$record['id']])); ?>">Documentos deste registro</a></p><?php } ?></details><?php } ?>
<?php if($can('hr_sensitive','edit')){foreach($recordLabels as $kind=>$label){?><details><summary>Adicionar: <?= $esc($label); ?></summary><?= form_open($url(['employee'=>$employee['id']]),['class'=>'hr-record-create']);$hidden('record_save',['employee_id'=>$employee['id'],'kind'=>$kind]);?><div class="company-settings-grid"><?php $recordFields($kind,[]); ?></div><button type="submit">Adicionar registro privado</button><?= form_close(); ?></details><?php }} ?>
<script>document.querySelectorAll('.hr-add-check-item').forEach(button=>button.addEventListener('click',()=>{const box=button.previousElementSibling;const n=box.children.length;if(n>=50)return;const row=box.firstElementChild.cloneNode(true);row.querySelectorAll('input').forEach(field=>{field.name=field.name.replace(/\[items\]\[\d+\]/,'[items]['+n+']');if(field.id){const old=field.id;field.id=old+'-item-'+n;row.querySelectorAll('label').forEach(label=>{if(label.htmlFor===old)label.htmlFor=field.id;});}if(field.type==='checkbox')field.checked=false;else if(field.type!=='hidden')field.value='';});box.appendChild(row);}));</script>
